 "content": "def transform(grid):
    # Recolor 2x2 objects that touch the grid boundary, and 2x2 objects
    # adjacent orthogonally to those, to color 8. Demos indicate color 8
    # propagates only one object-step from boundary objects.
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    q = (y+dy, x+dx)
                    if 0 <= q[0] < h and 0 <= q[1] < w and grid[q[0]][q[1]] == 2 and q not in seen:
                        seen.add(q); stack.append(q)
            comps.append(cells)
    chosen = set()
    for i, cells in enumerate(comps):
        if any(y == 0 or x == 0 or y == h-1 or x == w-1 for y,x in cells):
            chosen.add(i)
    # From boundary-touching components, recolor directly adjacent components
    # with a single blank cell between them (same row/column).
    for i, a in enumerate(comps):
        if i in chosen:
            continue
        for j in list(chosen):
            b = comps[j]
            if any((y == yy and abs(x-xx) <= 1) or (x == xx and abs(y-yy) <= 1)
                   for y,x in a for yy,xx in b):
                chosen.add(i); break
    out = [row[:] for row in grid]
    for i in chosen:
        for y,x in comps[i]:
            out[y][x] = 8
    return out
